{
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" git-gate --root \"<OUT>/.claude\""
          }
        ]
      },
      {
        "matcher": "Write|Edit|MultiEdit|NotebookEdit",
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" rule-gate --root \"<OUT>/.claude\""
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "matcher": "startup|clear",
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" context --root \"<OUT>/.claude\" || exit 0"
          }
        ]
      },
      {
        "matcher": "resume",
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" context --root \"<OUT>/.claude\" || exit 0"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" learn --memory \"<OUT>/.claude/memory\" || exit 0"
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"<HOME>/.geneseed/bin/geneseed-hook\" learn --memory \"<OUT>/.claude/memory\" || exit 0"
          }
        ]
      }
    ]
  },
  "claudeMdExcludes": [
    "<HOME>/.claude/CLAUDE.md"
  ]
}
